//! `vector` generated by `mlirformat tblgen` (`vector.gen.rs`) against the `mlir-opt` 22.1.8 fixtures.
//! One test crate per dialect so cargo builds them in parallel; `cargo test --features gen-tests`.

#[path = "../common/mod.rs"]
mod common;
#[path = "vector.gen.rs"]
mod vector;

#[test]
fn vector_matches_mlir_opt() {
    let mut opt = mlirformat::MlirOpt::new();
    opt.register::<vector::Vector>();
    common::Fixtures::check_dialect(&opt, "vector");
}
